// ValidatePayload (payload.go:156-173) - CL-side payload validation
func ValidatePayload(st state.BeaconState, payload interfaces.ExecutionData) error {
    random, err := helpers.RandaoMix(st, time.CurrentEpoch(st))
    if !bytes.Equal(payload.PrevRandao(), random) { return ErrInvalidPayloadPrevRandao }
    t, err := slots.StartTime(st.GenesisTime(), st.Slot())
    if payload.Timestamp() != uint64(t.Unix()) { return ErrInvalidPayloadTimeStamp }
    return nil
}
