// notifyNewPayload (execution_engine.go:219-296)
func (s *Service) notifyNewPayload(ctx context.Context, preStateVersion int,
    preStateHeader interfaces.ExecutionData, blk interfaces.ReadOnlySignedBeaconBlock) (bool, error) {
    // ... nil checks, version checks ...
    lastValidHash, err = s.cfg.ExecutionEngineCaller.NewPayload(ctx, payload, versionedHashes, parentRoot, requests)
    switch {
    case err == nil:  // EL returned VALID
        newPayloadValidNodeCount.Inc()
        return true, nil
    case errors.Is(err, execution.ErrAcceptedSyncingPayloadStatus):  // EL is SYNCING
        newPayloadOptimisticNodeCount.Inc()
        return false, nil  // optimistic acceptance
    case errors.Is(err, execution.ErrInvalidPayloadStatus):  // EL returned INVALID
        lvh := bytesutil.ToBytes32(lastValidHash)
        return false, invalidBlock{
            error:         ErrInvalidPayload,
            lastValidHash: lvh,
        }  // block rejected and pruned
    default:
        return false, errors.WithMessage(ErrUndefinedExecutionEngineError, err.Error())
    }
}

